## 4️⃣  Core Implementation Steps

### 4.1  Set Up the Project

```bash
npx create-next-app@latest my-ecommerce --typescript
cd my-ecommerce
npm install tailwindcss postcss autoprefixer
npx tailwindcss init -p
```

Add Tailwind to `globals.css`:

```css
@tailwind base;
@tailwind components;
@tailwind utilities;
```

Configure `tailwind.config.js` for dark mode, custom colors, etc.

### 4.2  Add State Management

```bash
npm install @tanstack/react-query zustand
```

Create a `useCart` hook:

```ts
// src/hooks/useCart.ts
import create from 'zustand';
import { persist } from 'zustand/middleware';

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  imageUrl: string;
}

interface CartState {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (id: string) => void;
  clearCart: () => void;
}

export const useCart = create<CartState>()(
  persist(
    (set, get) => ({
      items: [],
      addItem: (item) =>
        set((state) => {
          const existing = state.items.find((i) => i.id === item.id);
          if (existing) {
            return {
              items: state.items.map((i) =>
                i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i
              ),
            };
          }
          return { items: [...state.items, item] };
        }),
      removeItem: (id) =>
        set((state) => ({
          items: state.items.filter((i) => i.id !== id),
        })),
      clearCart: () => set({ items: [] }),
    }),
    { name: 'cart-storage' }
  )
);
```

### 4.3  Fetch Products with React Query

```ts
// src/hooks/useProducts.ts
import { useQuery } from '@tanstack/react-query';
import axios from 'axios';

export const fetchProducts = async () => {
  const { data } = await axios.get('/api/products');
  return data;
};

export const useProducts = () => {
  return useQuery(['products'], fetchProducts);
};
```

### 4.4  Build Reusable UI Components

```tsx
// src/components/ui/Button.tsx
import { ButtonHTMLAttributes } from 'react';
import clsx from 'clsx';

export const Button = ({
  children,
  className,
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement>) => (
  <button
    className={clsx(
      'px-4 py-2 rounded-md font-medium focus:outline-none focus:ring-2',
      className
    )}
    {...props}
  >
    {children}
  </button>
);
```

Use this button everywhere for consistent styling.

### 4.5  Create Product Card

```tsx
// src/components/product/Card.tsx
import Link from 'next/link';
import Image from 'next/image';
import { Button } from '@/components/ui/Button';
import { useCart } from '@/hooks/useCart';

export const ProductCard = ({ product }) => {
  const { addItem } = useCart();

  return (
    <div className="border rounded-lg overflow-hidden shadow-sm hover:shadow-md transition-shadow">
      <Link href={`/products/${product.slug}`}>
        <a>
          <Image
            src={product.imageUrl}
            alt={product.name}
            width={300}
            height={300}
            objectFit="cover"
          />
          <div className="p-4">
            <h3 className="font-semibold">{product.name}</h3>
            <p className="text-gray-600">${product.price}</p>
          </div>
        </a>
      </Link>
      <Button
        onClick={() => addItem(product)}
        className="w-full bg-indigo-600 text-white hover:bg-indigo-700"
      >
        Add to Cart
      </Button>
    </div>
  );
};
```

### 4.6  Implement Cart Sidebar

```tsx
// src/components/cart/CartSidebar.tsx
import { useCart } from '@/hooks/useCart';
import { Button } from '@/components/ui/Button';

export const CartSidebar = () => {
  const { items, clearCart } = useCart();

  return (
    <aside className="fixed right-0 top-0 h-full w-80 bg-white shadow-lg p-4 overflow-y-auto">
      <h2 className="text-xl font-bold mb-4">Your Cart</h2>
      {items.length === 0 && <p>Your cart is empty.</p>}
      {items.map((item) => (
        <div key={item.id} className="flex items-center mb-4">
          <img src={item.imageUrl} alt={item.name} className="w-16 h-16 mr-4" />
          <div className="flex-1">
            <p>{item.name}</p>
            <p>${item.price} × {item.quantity}</p>
          </div>
        </div>
      ))}
      <Button onClick={clearCart} className="mt-4 w-full bg-red-600 text-white">
        Clear Cart
      </Button>
    </aside>
  );
};
```

### 4.7  Checkout Flow

Use Stripe Elements inside a Next API route:

```ts
// src/pages/api/checkout.ts
import { stripe } from '@/lib/stripe';
import { NextApiRequest, NextApiResponse } from 'next';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return res.status(405).end();
  const { items } = req.body;
  const lineItems = items.map((i) => ({
    price_data: {
      currency: 'usd',
      product_data: { name: i.name },
      unit_amount: Math.round(i.price * 100),
    },
    quantity: i.quantity,
  }));
  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    line_items: lineItems,
    mode: 'payment',
    success_url: `${process.env.NEXT_PUBLIC_SITE_URL}/success`,
    cancel_url: `${process.env.NEXT_PUBLIC_SITE_URL}/cancel`,
  });
  res.json({ url: session.url });
}
```

On the client side, call this endpoint and redirect to Stripe’s hosted checkout.

### 4.8  Authentication

```ts
// src/lib/auth.ts
import NextAuth from 'next-auth';
import CredentialsProvider from 'next-auth/providers/credentials';
import { PrismaAdapter } from '@next-auth/prisma-adapter';
import prisma from './prisma';

export default NextAuth({
  adapter: PrismaAdapter(prisma),
  providers: [
    CredentialsProvider({
      async authorize(credentials) {
        const user = await prisma.user.findUnique({
          where: { email: credentials.email },
        });
        if (!user) throw new Error('No user found');
        // Verify password here (bcrypt)
        return user;
      },
    }),
  ],
  session: { strategy: 'jwt' },
});
```

Add a login page that uses `signIn` from `next-auth/react`.

### 4.9  SEO & Performance

* **SSR** for product pages (`getServerSideProps`) to expose meta tags.
* **Image Optimization** via `next/image`.
* **Code Splitting** automatically handled by Next.js.
* **Lazy Load** product images and components.
* **Critical CSS** via Tailwind’s purge.

### 4.10  Accessibility

* Use semantic HTML (`<header>`, `<nav>`, `<main>`, `<footer>`).
* Add `aria-labels` to interactive elements.
* Test with `axe-core` in Storybook or Cypress.

### 4.11  Testing

```bash
npm install --save-dev jest @testing-library/react @testing-library/jest-dom cypress
```

Example unit test for `ProductCard`:

```tsx
// __tests__/ProductCard.test.tsx
import { render, screen } from '@testing-library/react';
import { ProductCard } from '@/components/product/Card';

test('renders product name', () => {
  const product = { id: '1', name: 'Test', price: 99, imageUrl: '/test.jpg', slug: 'test' };
  render(<ProductCard product={product} />);
  expect(screen.getByText('Test')).toBeInTheDocument();
});
```

E2E test with Cypress for adding to cart:

```js
// cypress/integration/cart.spec.js
describe('Cart flow', () => {
  it('adds a product to cart', () => {
    cy.visit('/');
    cy.contains('Add to Cart').click();
    cy.get('.cart-sidebar').should('contain', 'Your Cart');
  });
});
```

### 4.12  Deployment

* **Vercel**: Connect your GitHub repo → automatic preview deployments.
* **Docker**: If you prefer self‑hosted, create a `Dockerfile`:

```dockerfile
FROM node:20-alpine
WORKDIR /app
COPY package*.json ./
RUN npm ci
COPY . .
RUN npm run build
EXPOSE 3000
CMD ["npm", "start"]
```

Push to a registry (Docker Hub, GitHub Packages) and deploy to a VPS or Kubernetes cluster.

